<script module>
  /* One counter for the whole program: every mark drawn gets its own pair of
     gradient ids, whatever order they appear in. */
  let gezeichnet = 0
  export function naechsteNummer() {
    return ++gezeichnet
  }
</script>

<script>
  /* The Extended Workflow mark: the house's lilac monogram.

     The one drawing in the program that is not a line sign. Extended
     Workflow is the thing this program is built around, and the rail says so
     before anybody reads a word — everything else on that strip is a stroke
     in the text colour, and this is lilac.

     Its own component and not a case in `Modulzeichen.svelte`: that file
     draws stroke signs, all of them sharing one idiom and one colour, and a
     filled monogram with two gradients has nothing in common with them
     beyond standing next to them.

     The gradients get a number of their own per instance. Two of these on
     one screen — the rail and the module head — would otherwise both reach
     for the same id, and the second one would silently take the first
     one's fill. */
  let { groesse = 28 } = $props()

  const nr = naechsteNummer()
</script>

