<style>
  /* A gentle shimmer, and the ONE animation the house allows on a mark.

     F5 struck every moving status dot, and that rule stands untouched: a
     status dot says what is happening and must be read, not watched. This
     is not a status dot — it is the product's own mark, and a mark may
     catch the eye. The status dot for Extended Workflow sits beside it and
     still stands perfectly still.

     The numbers are the approved ones and are not to be tuned by feel. */
  .eew {
    display: block;
    flex: none;
    animation: eewschimmer 3.2s ease-in-out infinite;
  }
  @keyframes eewschimmer {
    0%, 100% { filter: drop-shadow(0 0 5px rgba(201, 162, 39, 0.4)); }
    50% { filter: drop-shadow(0 0 11px rgba(231, 206, 122, 0.85)); }
  }
  /* Whoever asked for less motion gets the mark, standing. */
  @media (prefers-reduced-motion: reduce) {
    .eew {
      animation: none;
      filter: drop-shadow(0 0 5px rgba(201, 162, 39, 0.4));
    }
  }
</style>
